-- =============================================================================
-- Erro373 (imagem erro373.png) - Dados de TESTE para "Relatorio de Identificacao de Contas"
--           (FormSIGREIDC / SIGREIDCBO / SigReIdc.frx - etiquetas de identificacao)
-- O relatorio lista SigCdCli com GerBals = 1 (hoje 4 contas, NENHUMA com foto).
-- O erro "Field must be a Memo field" vinha justamente de FigJpgs NULL.
-- Cria 2 contas no grupo 11210 (clones da conta 1121001):
--   T373000001 CONTA TESTE 373 COM FOTO  -> FigJpgs = JPG (vbmp\BRA.jpg, 2328 bytes)
--   T373000002 CONTA TESTE 373 SEM FOTO  -> FigJpgs NULL (o caso que estourava)
-- Com os filtros da imagem (tudo em branco, Linha 1, Coluna 1) saem 6 etiquetas:
--   1110100001, 1121001, 3010110003, 3010210001, T373000001, T373000002
-- Marcador: SigCdCli.iclis LIKE 'T373%'
-- Idempotente. Limpeza: erro373_limpar_teste.sql
-- =============================================================================
SET NOCOUNT ON;
DELETE FROM SigCdCli WHERE iclis LIKE 'T373%';
SELECT * INTO #c FROM SigCdCli WHERE iclis = '1121001';
UPDATE #c SET iclis = 'T373000001', rclis = 'CONTA TESTE 373 COM FOTO', figuras = NULL,
              figjpgs = CAST(CAST( AS varbinary(max)) AS varchar(max));
INSERT INTO SigCdCli SELECT * FROM #c;
UPDATE #c SET iclis = 'T373000002', rclis = 'CONTA TESTE 373 SEM FOTO', figjpgs = NULL;
INSERT INTO SigCdCli SELECT * FROM #c;
DROP TABLE #c;
SELECT iclis, rclis, grupos, gerbals, DATALENGTH(figjpgs) bytes_foto,
       CASE WHEN figuras IS NULL THEN 'NULL' ELSE 'tem' END figuras
  FROM SigCdCli WHERE gerbals = 1 ORDER BY grupos, iclis;
